  cycle_nudge_menstruation_body: "월경 중이에요. 몸은 지금 다음 주기의 선도 난포를 고르기 시작해요. 따뜻한 음식과 깊은 잠 — 느껴지지 않아도 몸은 일하고 있어요.",
  cycle_nudge_follicular_headline: "기운이 *차오르는* 중",
  cycle_nudge_follicular_body: "에스트로겐이 오르고 있어요. 피부, 기분, 의욕 — 몸을 쌓아가는 시기예요. 근력 운동, 계획 세우기, 약속 잡기에 좋은 때예요.",
  cycle_nudge_ovulation_headline: "창이 *열렸어요*",
  cycle_nudge_ovulation_body: "가임 가능성이 가장 높은 때예요. 임신을 준비 중이라면 오늘과 앞으로 이틀이 이번 주기에서 가장 좋은 시기예요.",
  cycle_nudge_luteal_headline: "PMS는 *호르몬* 때문이지, 당신 탓이 아니에요",
  cycle_nudge_luteal_body: "프로게스테론이 줄어드는 시기예요. 마그네슘이 풍부한 음식(다크 초콜릿, 아몬드, 바나나)과 자기 전 산책이 생각보다 도움이 돼요.",
  cycle_nudge_late_headline: "며칠 *늦어지고* 있어요",
  cycle_nudge_late_body: "아직 결론은 아니에요. 기록해 왔다면 테스트를 해 보기 좋은 날이에요.",
  cycle_nudge_follicular_lh_headline: "*LH 검사*를 시작할 때",
  cycle_nudge_follicular_lh_body: "예상 배란 시기까지 며칠 남았어요. 오늘 밤이나 내일 아침 테스트를 해 보세요.",
  cycle_nudge_window_open_headline: "내일 창이 *열려요*",
  cycle_nudge_window_open_body: "24~48시간 안에 질 분비물이 달걀흰자처럼 변할 수 있어요. 살펴보세요.",
  cycle_nudge_ovulation_confirmed_headline: "*배란이 확인됐어요*",
  cycle_nudge_ovulation_confirmed_body: "체온이 3일간 기준선 위에 머물렀어요. 월경이 없으면 약 10일 뒤에 테스트해 보세요.",
  cycle_nudge_luteal_pms_headline: "PMS는 *호르몬* 때문이지, 당신 탓이 아니에요",
  cycle_nudge_luteal_pms_body: "프로게스테론이 줄어드는 시기예요. 마그네슘이 풍부한 음식과 자기 전 산책이 생각보다 도움이 돼요.",
  cycle_nudge_label: "오늘의 한마디",
  cycle_wallet_nudge: "오늘의 한마디",
  cycle_wallet_mood: "기분 및 증상",
  cycle_wallet_today: "오늘 한눈에",
  cycle_wallet_pillars: "나의 기둥",
  wallet_reminders_title: "알림",
  wallet_exams_title: "검사",
  wallet_askGrandma_title: "Grandma에게 물어보기",
  wallet_rewards_title: "보상",
  wallet_channels_title: "채널",
  wallet_village_title: "마을",
  wallet_pickTitle: "내 지갑 꾸미기",
  cycle_nudge_from: "보낸 사람",
  cycle_nudge_read_more: "더 읽기 →",
  cycle_nudge_reflect_from: "나를 위한 시간",
  cycle_nudge_log_it: "기록하기 →",
  cycle_nudge_menstruation_iron_headline: "*철분*을 채워 주세요",
  cycle_nudge_menstruation_iron_body: "출혈이 있으면 철분이 줄어들어요. 시금치나 렌틸콩 요리에 새콤한 과일을 곁들여 보세요. 비타민 C가 흡수를 대략 두 배로 높여요.",
  cycle_nudge_menstruation_warmth_headline: "오늘은 스스로에게 *다정하게*",
  cycle_nudge_menstruation_warmth_body: "프로스타글란딘이 생리통을 일으켜요. 온열 패드와 느린 움직임이 도움이 될 수 있어요. 지금은 원래 기력이 가장 낮은 때이기도 해요.",
  cycle_nudge_follicular_plan_headline: "*계획 세우기* 좋은 날",
  cycle_nudge_follicular_plan_body: "오르는 에스트로겐이 집중력과 기분을 또렷하게 해요. 어려운 생각, 강도 높은 운동, 미뤄둔 대화에 이 시기를 써 보세요.",
  cycle_nudge_follicular_hydrate_headline: "*질 분비물*을 살펴보세요",
  cycle_nudge_follicular_hydrate_body: "가임 시기가 가까워지면 더 맑고 잘 늘어나기 시작해요. 분비물은 대부분 물이라, 하루 2~2.5리터를 마시면 변화를 보기 쉬워요.",
  cycle_nudge_ovulation_timing_headline: "*이틀 전*이 가장 중요해요",
  cycle_nudge_ovulation_timing_body: "정자는 최대 5일, 난자는 12~24시간만 살아요. 정확한 하루보다 그 앞의 며칠을 노려 보세요. 정확성보다 횟수예요.",
  cycle_nudge_luteal_sleep_headline: "이번 주는 *잠*을 지켜요",
  cycle_nudge_luteal_sleep_body: "프로게스테론이 체온을 올리고 잠을 얕게 만들어요. 시원한 방과 조금 이른 마무리가 기분을 생각보다 안정시켜요.",
  cycle_nudge_luteal_move_headline: "걷기가 *걱정의 소용돌이*보다 나아요",
  cycle_nudge_luteal_move_body: "황체기 후반의 처짐은 호르몬 때문이에요. 당신 삶에 대한 판결이 아니에요. 햇빛 속에서 20분 움직이면 스크롤보다 마음이 잘 풀려요.",
  cycle_nudge_fertility_follicular_headline: "곧 *창이 열려요*",
  cycle_nudge_fertility_follicular_body: "에스트로겐이 배란을 향해 오르고 있어요. 배란 전 5일이 가임 시기예요. 정자가 난자를 그만큼 기다릴 수 있거든요.",
  cycle_nudge_fertility_luteal_headline: "창이 *닫혔어요*",
  cycle_nudge_fertility_luteal_body: "난자는 12~24시간만 살기 때문에 주기의 이 시기는 가능성이 낮아요. 검사나 타이밍을 맞췄다면 이제는 기다리는 시간이에요.",
  cycle_nudge_fertility_menstruation_headline: "*새* 주기가 시작돼요",
  cycle_nudge_fertility_menstruation_body: "첫날에 시계가 다시 시작돼요. 다음 가임 시기는 대략 2주 뒤예요. 열리기 전까지 편히 쉬며 준비하는 시간이에요.",
  cycle_nudge_reflect_mood_headline: "오늘 기분이 *어때요*?",
  cycle_nudge_reflect_mood_body: "짧은 기분 체크가 쌓이면 흐름이 보여요. 몇 주기만 기록해도 시기별 패턴이 훨씬 잘 보여요.",
  cycle_nudge_reflect_symptom_headline: "오늘 느껴지는 게 *있나요*?",
  cycle_nudge_reflect_symptom_body: "복통, 가슴 통증, 두통이 있나요? 증상을 기록하면 나와 의사 선생님이 내 몸의 흐름을 파악하는 데 도움이 돼요.",
  cycle_nudge_reflect_energy_headline: "*기운*은 어느 정도인가요?",
  cycle_nudge_reflect_energy_body: "월경 전에는 기운이 자연스럽게 내려가요. 오늘 적어 두면 거스르지 않고 나만의 리듬에 맞춰 계획할 수 있어요.",
  cycle_nudge_nutrition_luteal_headline: "*마그네슘*을 챙겨요",
  cycle_nudge_nutrition_luteal_body: "다크 초콜릿, 아몬드, 호박씨, 바나나는 주기 후반의 통증을 덜고 기분을 안정시켜요. 복합 탄수화물을 곁들이면 식욕도 누그러져요.",
  cycle_nudge_nutrition_ovulation_headline: "*난자*를 챙겨 주세요",
  cycle_nudge_nutrition_ovulation_body: "베리, 잎채소, 견과류 같은 항산화 식품이 난자 건강을 도와요. 아연(호박씨, 병아리콩)은 배란기 즈음에 특히 중요해요.",
  cycle_nudge_edu_menstruation_headline: "월경은 *첫째* 날이에요",
  cycle_nudge_edu_menstruation_body: "주기 1일은 소량 출혈이 아닌 본격적인 출혈이 시작된 날이에요. 모든 예측이 이날을 기준으로 계산돼요. 정확히 기록할수록 모든 게 또렷해져요.",
  cycle_nudge_edu_follicular_headline: "난포 *하나*가 이겨요",
  cycle_nudge_edu_follicular_body: "주기마다 여러 난포가 자라기 시작하지만, 보통 하나만 성숙해 난자를 내보내요. 그 선택을 이끄는 건 오르는 에스트로겐이에요.",
  cycle_nudge_edu_ovulation_headline: "*36시간*의 일",
  cycle_nudge_edu_ovulation_body: "배란은 짧아요. LH 급증 후 약 24~36시간 안에 난자가 나와요. 그래서 LH 스트립은 배란이 아닌 급증을 잡도록 맞춰져 있어요.",
  cycle_nudge_edu_luteal_headline: "*2주*의 기다림",
  cycle_nudge_edu_luteal_body: "황체기는 놀랄 만큼 일정해요. 주기 길이와 상관없이 보통 12~14일이에요. 주기 길이의 차이는 대부분 전반부에서 와요.",
