  guidelines_rule2Body: "다른 사람의 개인 정보나 건강 정보를 공유하지 마세요. 내 가족에 대해 밝히는 것도 신중하게 해 주세요.",
  guidelines_rule3Title: "진단 말고 응원을 나눠요",
  guidelines_rule3Body: "경험과 격려를 나눠 주세요. 의학적 지시는 안 돼요. 건강이 걱정되는 분께는 꼭 의사와 상담하도록 알려 주세요.",
  guidelines_rule4Title: "스팸이나 판매는 안 돼요",
  guidelines_rule4Body: "커뮤니티는 홍보가 아니라 연결을 위한 곳이에요. 장터 게시물은 피드가 아니라 교환 코너에 올려 주세요.",
  guidelines_rule5Title: "안전하게 지켜요",
  guidelines_rule5Body: "자해, 아이에 대한 위험, 불법을 부추기는 콘텐츠는 안 돼요. 삭제하고 계정을 정지할 수 있어요.",
  guidelines_sectionReport: "문제를 발견했다면",
  guidelines_reportBody: "게시물이나 메시지를 길게 눌러 신고하거나 그 사람을 차단해요. 신고는 비공개이며 팀이 살펴봐요. 응급 상황에는 꼭 현지 응급 서비스에 연락해 주세요.",
  guidelines_footer: "이 규칙을 어기면 콘텐츠가 삭제되거나 계정이 정지될 수 있어요. 이 커뮤니티를 안전하게 지켜 줘서 고마워요.",
