  sw2_leap19_name: "사건",
  sw2_leap19_desc: "행동이 순서대로 일어난다는 것을 이해해요",
  sw2_leap19_brain: "이 시기에는 아기가 세상을 하나의 흐릿한 덩어리가 아니라 일련의 사건으로 느끼기 시작하는 경우가 많아요. 행동에는 시작과 중간과 끝이 있죠. 원인과 결과를 생각하기 시작하는 때이고, 갑자기 모든 게 신기해 보이는 이유이기도 해요.",
  sw2_leap19_tip: "까꿍 놀이처럼 원인과 결과가 보이는 간단한 놀이를 해 보세요. 아기는 일에는 예상할 수 있는 결과가 있다는 걸 배우는 중이에요.",
  sw2_leap19_ph0: "딱 붙어 있으려 하고, 내려놓으면 울고, 잠이 흐트러져요. 새로운 일이 한꺼번에 많아서 아기가 지칠 수 있어요.",
  sw2_leap19_ph1: "아기는 행동 다음에 무슨 일이 생기는지 연결해 보느라 바쁜 경우가 많아요. 밀어 보고, 떨어뜨리고, 가만히 지켜보죠.",
  sw2_leap19_ph2: "일부러 손을 뻗기 시작하고, 물건이 사라져도 있다는 걸 조금씩 알게 돼요. 떨어뜨린 물건을 찾아봐요.",
  sw2_leap19_sg0: "분리불안이 심해져요",
  sw2_leap19_sg1: "많이 안기려 해요",
  sw2_leap19_sg2: "장난감이 떨어지면 울어요",
  sw2_leap19_sg3: "낮잠을 거부해요",
  sw2_leap19_sg4: "계속 놀아 달라고 해요",
  sw2_leap19_sg5: "일과가 바뀌면 짜증을 내요",
  sw2_leap19_sk0: "일부러 손을 뻗어 잡아요",
  sw2_leap19_sk1: "장난감을 흔들고 두드려요",
  sw2_leap19_sk2: "익숙한 놀이를 알아봐요",
  sw2_leap19_sk3: "\"위\"와 \"아래\"를 이해해요",
  sw2_leap19_sk4: "움직이는 물건을 눈으로 따라가요",
  sw2_leap19_sk5: "깜짝 놀라게 해 주면 웃어요",
  sw2_leap19_ac0: "까꿍 놀이와 숨바꼭질",
  sw2_leap19_ac1: "공을 서로 굴려요",
  sw2_leap19_ac2: "간단한 인과 장난감(누르면 소리 나는 것)",
  sw2_leap19_ac3: "하루 일과를 단계별로 말해 주세요",
  sw2_leap5_name: "달라지는 감각",
  sw2_leap5_desc: "아기가 더 풍성한 감각의 세계를 발견해요",
  sw2_leap5_brain: "이 무렵 아기는 감각으로 훨씬 더 많은 것을 느끼기 시작할 수 있어요. 더 또렷한 모습, 더 풍부한 소리, 새로운 몸의 느낌까지요. 벅차면서도 멋진 일이에요.",
  sw2_leap5_ph0: "더 많이 울고, 더 안기고 싶어 하고, 잠이 불안해지는 일이 흔해요. 아기가 새로운 감각 정보를 많이 받아들이고 있을 수 있어요.",
  sw2_leap5_ph1: "아기가 새로운 모습과 소리를 많이 받아들이고 있어요. 보채는 게 절정에 달했다가 가라앉을 수 있어요.",
  sw2_leap5_ph2: "새로운 감각에 대한 인식이 피어나요. 깨어 있는 시간이 길어지고 더 의도적으로 바라보는 모습을 보게 될 거예요.",
  sw2_leap5_sg0: "평소보다 더 울어요",
  sw2_leap5_sg1: "계속 먹고 싶어 해요",
  sw2_leap5_sg2: "달래기 어려워요",
  sw2_leap5_sg3: "가까이 있는 걸 좋아해요",
  sw2_leap5_sg4: "더 쉽게 놀라요",
  sw2_leap5_sg5: "옷 벗는 걸 싫어해요",
  sw2_leap5_sk0: "빛과 소리에 반응해요",
  sw2_leap5_sk1: "눈으로 더 부드럽게 따라가요",
  sw2_leap5_sk2: "사회적 미소가 나타나요",
  sw2_leap5_sk3: "깨어 있는 시간이 늘어요",
  sw2_leap5_sk4: "목소리 쪽으로 고개를 돌려요",
  sw2_leap5_sk5: "대비가 강한 무늬를 알아봐요",
  sw2_leap5_ac0: "아기를 바깥쪽으로 안아 방 안을 구경하게 해 주세요",
  sw2_leap5_ac1: "흑백 대비가 강한 카드를 보여 주세요",
  sw2_leap5_ac2: "하는 일을 소리 내어 이야기해 주세요",
  sw2_leap5_ac3: "차분한 순간에 부드럽게 마사지해 주세요",
  sw2_leap5_tip: "지금은 살을 맞대는 스킨십이 큰 힘이 돼요. 아기띠와 부드러운 흔들기가 보채는 날에 도움이 될 수 있어요.",
  sw3_period_day: "일",
