  sw3_ins_narrTop: "이번 달 {{name}}의 가장 많은 기록은 {{type}}으로 {{n}}건이에요.",
  sw3_ins_narrStreak: "{{n}}일 연속으로 기록 중이에요. 계속 이어가 봐요!",
  sw3_ins_narrRowMany: "{{n}}일 연속으로 기록했어요.",
