  sw2_an_feedsDetail: "{{name}}은(는) 기록한 날 하루 약 {{avg}}회 수유했어요. 수유할 때마다 기록하면 흐름을 보기 쉬워요.",
  sw2_an_mealsDetail: "{{name}}은(는) 기록한 날 하루 약 {{avg}}회 식사했고, {{pct}}%가 “잘 먹었어요”로 기록됐어요. 새로운 음식은 받아들이기까지 10~15번 걸리는 경우가 많아요. 익숙한 음식과 함께, 일정한 식사 시간에 주세요.",
  sw2_an_moodsTitle: "이번 주 기분",
  sw2_an_moodsBody: "기록한 기분: {{n}}회 — “{{top}}”이(가) 가장 많았고, 짜증·보챔은 {{fussy}}회예요.",
  sw2_an_moodsDetailFussy: "{{name}}의 기분 중 가장 많이 기록된 것은 “{{top}}”이고, {{total}}회 중 {{fussy}}회가 짜증·보챔으로 기록됐어요. 보챔은 이가 나는 시기(6~24개월에 흔해요), 성장 급등기, 짧은 잠, 일과 변화와 함께 나타나는 경우가 많아요. 더 안아 주고 일과를 꾸준히 하면 도움이 될 수 있어요. 걱정되면 소아과 의사와 상담하세요.",
  sw2_an_moodsDetailCalm: "{{name}}의 기분 중 가장 많이 기록된 것은 “{{top}}”이고, 짜증·보챔 기록은 없었어요. 꾸준한 일과와 충분한 잠은 편안한 하루와 함께하는 경우가 많아요.",
  sw2_an_actTitle: "하루 활동 기준",
  sw2_an_actBody: "일반적인 기준: {{age}}은(는) 하루 {{target}}.",
  sw2_an_actTargetTummy: "20~30분 배밀이 시간",
  sw2_an_actTargetPlay: "60분 활동적인 놀이",
  sw2_an_actDetailBaby: "배밀이 시간은 뒤집기, 앉기, 기기에 필요한 목·어깨·몸통 힘을 키워 줘요. 2~3분부터 시작해 하루 동안 나눠서 20~30분까지 늘려 보세요. 함께 바닥에 누우면 더 즐거워요.",
  sw2_an_actDetailToddler: "활발한 놀이는 운동 능력, 수면, 기분에 도움이 돼요. 바깥 놀이는 햇빛과 맑은 공기, 탐색할 거리를 더해 줘요. 20분씩 3번만 해도 충분히 쌓여요.",
  sw2_an_growthTitle: "성장 기록하기",
  sw2_an_growthBody: "{{name}}의 몸무게와 키를 기록하면 시간에 따른 변화를 볼 수 있어요.",
  sw2_an_growthDetail: "측정값이 쌓일수록 성장 그래프가 더 유용해져요. 소아과에 다녀올 때마다 캘린더 → 성장에서 몸무게, 키, 머리둘레를 기록해 보세요.",
  sw2_an_diaperTitle: "이번 주 기저귀",
  sw2_an_diaperLowBody: "하루 평균 기저귀 {{avg}}개 — 어린 아기의 일반적인 기준은 소변 기저귀 하루 6개 이상이에요.",
  sw2_an_diaperLowDetail: "{{name}}은(는) 최근 {{days}}일 동안 하루 평균 기저귀 {{avg}}개를 썼어요. 생후 6개월 미만의 일반적인 기준은 소변 기저귀 하루 6개 이상이에요. 수유가 걱정되면 소아과에 문의하세요.",
